// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "../bridge";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface EnrolmentOut {
  enrolment_id: number;
  enrolment_number: string;
  programme_id: number;
  programme_name: string;
  patient_id: number;
  mrn: string;
  patient_name: string;
  card_number: string | null;
  status: "Active" | "Completed" | "TransferredOut" | "Discontinued";
  enrolled_at: string;
  enrolled_by: number;
  closed_at: string | null;
  close_note: string | null;
  row_version: number;
  entries: EntryOut[];
}

export interface EntryOut {
  entry_id: number;
  enrolment_id: number;
  service: string;
  given_at: string;
  batch_number: string | null;
  next_due_on: string | null;
  note: string | null;
  given_by: number;
  given_by_stamp: AuthorStampOut;
  created_at: string;
}

/** The author stamp of a clinical entry (MSDS IMS 147), as the author's staff record stood when they signed it (SQL hms_author_stamp / hms_employee_stamp, migration 0013 [STP]). Show it under the entry on screen and print `text` under it on paper. */
export interface AuthorStampOut {
  employee_id: number | null;
  user_id: number | null;
  name: string;
  /** Designation and specialty, e.g. "Medical Officer, General Medicine" */
  designation: string | null;
  /** Council registration, e.g. "PMDC 12345-P" or "PNC 67890" */
  registration: string | null;
  /** When the entry was signed, reported or verified */
  at: string;
  /** The printed line: name, designation, registration, date and time */
  text: string;
}

export interface EnrolIn {
  programme_id: number;
  /** The programme's own card or register number (an EPI card, a TB-DOTS register number) */
  card_number?: string | null;
}

export interface ProgrammeEntryIn {
  /** One of the programme's services */
  service: string;
  /** When it was given; not in the future */
  given_at: string;
  /** A vaccine's or a medicine's batch */
  batch_number?: string | null;
  /** As the programme's card says; Haspataal computes no schedule */
  next_due_on?: string | null;
  note?: string | null;
}

export interface EnrolmentCloseIn {
  status: "Completed" | "TransferredOut" | "Discontinued";
  /** Required for TransferredOut (where to) and Discontinued (why) */
  note?: string | null;
}

export interface ProgrammeOut {
  programme_id: number;
  name: string;
  kind: "Immunization" | "FamilyPlanning" | "Tuberculosis" | "Malaria" | "Dengue" | "Other";
  national_programme: string | null;
  guideline: string;
  services: string[];
  is_offered: boolean;
  active_enrolments: number;
  row_version: number;
}

export interface DueOut {
  enrolment_id: number;
  enrolment_number: string;
  programme_id: number;
  programme_name: string;
  patient_id: number;
  mrn: string;
  patient_name: string;
  mobile: string | null;
  card_number: string | null;
  last_service: string;
  last_given_at: string;
  /** From the latest entry, as the programme's card says */
  next_due_on: string;
}

/** A patient's preventive programmes — GET /api/v1/patients/{patient_id}/programmes (who may call: holders of programme.view or programme.manage). */
export function forPatientPatientsProgrammes(patient_id: number): Promise<EnrolmentOut[]> {
  return api<EnrolmentOut[]>("GET", `/patients/${patient_id}/programmes`, undefined);
}

/** Enrol a patient in a programme — POST /api/v1/patients/{patient_id}/programmes (who may call: holders of programme.give). */
export function enrol(patient_id: number, body: EnrolIn): Promise<EnrolmentOut> {
  return api<EnrolmentOut>("POST", `/patients/${patient_id}/programmes`, body, { idempotent: true });
}

/** Record a service given — POST /api/v1/programme-enrolments/{enrolment_id}/entries (who may call: holders of programme.give). */
export function addEntry(enrolment_id: number, body: ProgrammeEntryIn): Promise<EnrolmentOut> {
  return api<EnrolmentOut>("POST", `/programme-enrolments/${enrolment_id}/entries`, body, { idempotent: true });
}

/** Complete, transfer out or discontinue an enrolment — POST /api/v1/programme-enrolments/{enrolment_id}/close (who may call: holders of programme.give). */
export function closeProgrammeEnrolments(enrolment_id: number, body: EnrolmentCloseIn): Promise<EnrolmentOut> {
  return api<EnrolmentOut>("POST", `/programme-enrolments/${enrolment_id}/close`, body);
}

/** The preventive programmes offered — GET /api/v1/preventive-programmes (who may call: holders of programme.view or programme.manage or msds.view). */
export function listProgrammes(query?: { include_inactive?: boolean }): Promise<ProgrammeOut[]> {
  return api<ProgrammeOut[]>("GET", withQuery(`/preventive-programmes`, query), undefined);
}

/** The patients due for their next service — GET /api/v1/preventive-programmes/due (who may call: holders of programme.view). */
export function due(query: { on: string; programme_id?: number | null; limit?: number; before_id?: number | null }): Promise<DueOut[]> {
  return api<DueOut[]>("GET", withQuery(`/preventive-programmes/due`, query), undefined);
}
